// Review directions, never a failed prediction promoted into an experiment.
import {failedComparisons} from './course-stock.mjs';
export function noStockEvidence(s,d){
 const n=d?.efficiency,z=n?.inventory;if(d?.status!=='N'||!z||z.feasible?.length)return null;
 const declared=z.entries.filter(x=>x.available),tested=z.entries.filter(x=>x.evaluated>0),gaps=tested.filter(x=>x.interval?.ok),unknown=[...new Set(declared.flatMap(x=>x.checks||[]))],h=d.selectivityHistory;
 const state=!z.ok?'search-inputs':!declared.length?'inventory-pending':!tested.length?'stock-excluded':gaps.length?'grid-gap':'no-feasible-stock';
 const headline={'search-inputs':'Search incomplete — correct inputs before judging stock.','inventory-pending':'Actual stock not declared — no stock feasibility conclusion yet.','stock-excluded':'Declared stock could not enter the N-only search — review exclusions.','grid-gap':'A continuous feasible flow interval exists — refine the grid before rejecting stock.','no-feasible-stock':'No passing numerical plan in the tested stock and flow range — choose a review direction, not a failing injection.'}[state];
 const fmt=(x,k=3)=>Number.isFinite(x)?x.toFixed(k):'unknown';
 const reference=`${d.label}: ${d.n}/${s.settings.specs.peakCount.value} peaks; experimental last tR ${fmt(d.last)} min; derived worst Rs ${fmt(d.rs,6)}; measured full-trace BP ${fmt(d.safety?.value,1)} psi. Required: tR ${s.settings.specs.lastPeak.op} ${s.settings.specs.lastPeak.value} min, Rs ${s.settings.specs.minRs.op} ${s.settings.specs.minRs.value}, BP ${s.settings.specs.pressure.op} ${s.settings.specs.pressure.value} psi. Each candidate also uses its own entered limits.`;
 const coverage=`${declared.length} declared available; ${tested.length} tested columns; ${z.evaluated} column × flow comparisons. F ${z.criteria.flowMin??'unknown'}–${z.criteria.flowMax??'unknown'} mL/min, step ${z.criteria.flowStep??'unknown'}. ${z.ok?'Continuous feasible intervals checked as well.':z.reason} This is not a global impossibility claim.`;
 const directions=[];
 if(state==='search-inputs')directions.push({id:'inputs',title:'Correct search / reference inputs',why:z.reason,next:'Enter a valid range and step or the missing reference data, then recompute. Do not invent measurements.',target:'inventory-search'});
 if(state==='inventory-pending'||state==='stock-excluded')directions.push({id:'inventory',title:'Record / verify actual stock',why:state==='inventory-pending'?'No physical column is currently declared available.':declared.map(x=>`${x.column.label}: ${x.reasons.join('; ')}`).join(' '),next:'Enter actual L, ID, particle size, product family and construction. Check chemistry and the candidate’s own limits. Different chemistry needs Retention / Selectivity data, not an N-only prediction.',target:'inventory-search'});
 if(gaps.length)directions.push({id:'grid',title:'Refine the flow grid first',why:gaps.map(x=>`${x.column.label}: predicted feasible F ${fmt(x.interval.min,6)}–${fmt(x.interval.max,6)} mL/min`).join('; '),next:'Narrow the range around these intervals and reduce the step within actual pump limits. Recalculate; do not round a failed boundary into a pass.',target:'inventory-search'});
 if(state==='no-feasible-stock')directions.push({id:'stock',title:'Check other real same-phase columns / permitted flows',why:'No intersection of time, Rs, pressure and flow bounds was found for the tested columns in this range.',next:'Record a different available L / ID / particle size or verified same-selectivity construction. Widen flow range only within actual hardware limits. Hypothetical dimensions are comparisons, not stock.',target:'inventory-search'});
 const performed=(h?.steps||[]).filter(x=>x.runs.length).map(x=>`${x.label}: ${x.runs.map(r=>r.label).join(', ')}`).join('; '),next=h?.next;
 directions.push({id:'selectivity',title:'Review remaining Selectivity options',why:`${d.label} has Rs ${fmt(d.rs,6)} versus ${s.settings.specs.minRs.value} required. N eligibility / the ideal Rs floor does not prove a suitable physical column exists. ${performed?`Recorded comparisons: ${performed}.`:'No matched temperature / solvent comparisons are recorded for this reference.'}`,next:next?.temp?`Next unrecorded comparison in retained history: ${next.solvent} at ${next.B??'a documented equivalent'} %B, ${next.temp} °C. ${next.why} Review full method and limits before choosing it; this option is not automatically selected or predicted to pass.`:'Review temperature / solvent evidence, optional intermediate strength or another actually available ligand. New chemistry needs its own Retention data and cannot borrow this N prediction.',target:'cycle-chain'});
 directions.push({id:'gradient',title:'Consider Gradient scouting as an optional new strategy',why:'Changing elution strength with time may address the time / retention trade-off; these isocratic data do not predict a successful gradient separation.',next:'Open Gradient planning. Establish a program, initial/final strength, hold, flow, column volume, dwell and re-equilibration; check hardware and B-bottle contents. Validate using a real gradient CSV and full pressure trace. No guaranteed Rs or complete optimum is issued.',target:'gradient-module'});
 directions.push({id:'criteria',title:'Review feasibility with the laboratory supervisor',why:'Method acceptance criteria and instrument / column ratings are different. Raising a method limit cannot raise a hardware rating.',next:'Discuss a justified revised specification or a different rated setup only if the assignment / method permits it. Criteria are not relaxed and UPLC is not prescribed automatically.',target:'course-specifications'});
 return {state,headline,sourceRunId:d.runId,sourceRunLabel:d.label,reference,coverage,declared:declared.length,tested:tested.length,blockRecipe:declared.length>0,directions,unknown,bestFailed:failedComparisons(z),exclusions:z.entries.filter(x=>x.reasons?.length).map(x=>({columnId:x.id,label:x.column.label,reasons:x.reasons,rejectCounts:x.rejectCounts,interval:x.interval})),planningOnly:true,performed:false,scope:'Directions for review, not selected experiment conditions. Reference raw CSVs remain unchanged. Recompute after stock, limits, range or specifications change; only an all-spec numerical result may become a conditional stock recipe.'};
}
